// The steps of the 12 cases of v1, the 2 more cases and the 12 cuts. Each step is in the words of the guidebook, and each step cites the page that tells it.
// The steps are full from `ready` to `P3`. `P4` and `P5` are an outline. Each cell with no step has a marked gap in `gaps.ts`.

import type { Phase, Step } from "@mark1russell7/guidebook-plans";

/** One row of a key: the phase, a short name, the action, the sources and the needs that the step protects. */
type Row = readonly [phase: Phase, name: string, action: string, sources: readonly string[], needs?: readonly string[], reasoning?: string];

/** This function makes the steps of a key from its rows. The order of a step is its position among the rows of its phase. */
function stepsOf(on: string, rows: readonly Row[]): Step[] {
  const count = new Map<Phase, number>();
  return rows.map(([phase, name, action, sources, needs = [], reasoning]) => {
    const order = (count.get(phase) ?? 0) + 1;
    count.set(phase, order);
    return { id: `${on}.${phase}.${name}`, on, phase, needs, do: action, order, sources, ...(reasoning === undefined ? {} : { reasoning }) };
  });
}

